import sys
from collections import deque

MOD = 998244353
n = int(sys.stdin.readline())
p = [0] * n
for _ in range(n):
    x, y = map(int, sys.stdin.readline().split())
    p[x - 1] = y - 1

comp = [[False] * n for _ in range(n)]
for i in range(n):
    for j in range(n):
        comp[i][j] = (i - j) * (p[i] - p[j]) > 0

seen = {(1 << n) - 1}
q = deque(seen)
while q:
    s = q.popleft()
    for k in range(n):
        if (s >> k) & 1:
            t = 1 << k
            z = s
            while z:
                b = z & -z
                i = b.bit_length() - 1
                z -= b
                if not comp[k][i]:
                    t |= b
            if t not in seen:
                seen.add(t)
                q.append(t)
print(len(seen) % MOD)

