import sys
MOD=998244353
def main():
 data=list(map(int,sys.stdin.buffer.read().split()))
 n=data[0]; a=data[1:]
 fac=[]
 primes=[]
 for x in a:
  d={}; q=x; p=2
  while p*p<=q:
   while q%p==0: d[p]=d.get(p,0)+1; q//=p
   p+=1
  if q>1:d[q]=d.get(q,0)+1
  fac.append(d)
  for p in d:
   if p not in primes:primes.append(p)
 ans=1
 for p in primes:
  dp={0:1}; length=1
  for d in fac:
   e=d.get(p,0)
   nd={}
   for h,val in dp.items():
    for delta in ([-e,e] if e else [0]):
     y=h+delta
     if y<0:
      z=-y; nh=0; mul=pow(p,z*length,MOD)
     else:
      nh=y; mul=pow(p,nh,MOD)
     nd[nh]=(nd.get(nh,0)+val*mul)%MOD
   dp=nd; length+=1
  ans=ans*sum(dp.values())%MOD
 print(ans)
if __name__=='__main__':main()

