from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        at = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            at[b].append((a, i))
        first = second = 0
        first_id = -1
        gain = [0] * m
        base = 0
        for r in range(1, n + 1):
            for a, idx in at[r]:
                if a >= first:
                    second = first
                    first, first_id = a, idx
                elif a > second:
                    second = a
            base += r - first
            if first_id >= 0:
                gain[first_id] += first - second
        return base + max(gain)

