from math import comb
class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = len(s)
        ways = [0] * (n + 1)
        ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                rem = n - i - 1
                for c in range(ones, n + 1):
                    need = c - ones
                    if 0 <= need <= rem:
                        ways[c] += comb(rem, need)
                ones += 1
        ans = 0
        for c in range(1, n + 1):
            steps = 0
            x = c
            while x != 1:
                x = x.bit_count()
                steps += 1
            if steps + 1 <= k:
                ans += ways[c]
        return ans % (10**9 + 7)

