import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]; A=data[1:]
    U=(1<<100)-A[-1]-1
    ans=0
    def feasible(r, mod):
        x=r if r else mod
        return x<=U
    def dfs(r, t, unresolved, score):
        nonlocal ans
        if not unresolved:
            if feasible(r,1<<t): ans=max(ans,score)
            return
        if t==100:
            if feasible(r,1<<t): ans=max(ans,score)
            return
        step=1<<t
        mod=step<<1
        for b in (0,1):
            nr=r+b*step
            nu=[]
            for a in unresolved:
                if (nr+a)%mod==0: nu.append(a)
            gain=len(unresolved)-len(nu) if t%2==0 else 0
            dfs(nr,t+1,nu,score+gain)
    dfs(0,0,A,0)
    print(ans)
