    mid = (lo + hi) // 2
    if mid**3 <= N:
        lo = mid
    else:
        hi = mid
for d in range(1, lo + 1):
    if N % d:
        continue
    disc = 12 * (N // d) - 3 * d * d
    if disc < 0:
        continue
    r = math.isqrt(disc)
    if r * r != disc:
        continue
    num = r - 3 * d
    if num > 0 and num % 6 == 0:
        y = num // 6
        print(y + d, y)
        break
else:
    print(-1)

