from typing import List
from math import factorial

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = (n + 1) // 2
        evens = n // 2
        used = [False] * (n + 1)
        ans = []
        expected = 0  # 0 means either parity; otherwise required parity (1 odd, 2 even)

        def ways(o, e, first):
            m = o + e
            if m == 0:
                return 1
            if first == 1:
                need_o, need_e = (m + 1) // 2, m // 2
            else:
                need_e, need_o = (m + 1) // 2, m // 2
            if o != need_o or e != need_e:
                return 0
            return factorial(o) * factorial(e)

        for pos in range(n):
            picked = False
            for x in range(1, n + 1):
                if used[x]:
                    continue
                p = 1 if x % 2 else 2
                if expected and p != expected:
                    continue
                o, e = odds, evens
                if p == 1:
                    o -= 1
                else:
                    e -= 1
                count = ways(o, e, 3 - p)
                if k > count:
                    k -= count
                else:
                    ans.append(x)
                    used[x] = True
                    odds, evens = o, e
                    expected = 3 - p
                    picked = True
                    break
            if not picked:
                return []
        return ans

