    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        coeff = []
        p10 = [pow(10, i, k) for i in range(n)]
        for i in range(m):
            j = n - 1 - i
            coeff.append((p10[i] + (p10[j] if j != i else 0)) % k)
        full = (1 << k) - 1
        suffix = [0] * (m + 1)
        suffix[m] = 1
        for i in range(m - 1, -1, -1):
            c = coeff[i]
            lo = 1 if i == 0 else 0
            mask = 0
            for d in range(lo, 10):
                s = d * c % k
                nxt = suffix[i + 1]
                if s:
                    mask |= ((nxt << s) | (nxt >> (k - s))) & full
                else:
                    mask |= nxt
            suffix[i] = mask
        digits = [0] * m
        rem = 0
        for i, c in enumerate(coeff):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                need = (-(rem + d * c)) % k
                if (suffix[i + 1] >> need) & 1:
                    digits[i] = d
                    rem = (rem + d * c) % k
                    break
        out = ['0'] * n
        for i, d in enumerate(digits):
            out[i] = out[n - 1 - i] = str(d)
        return ''.join(out)

