from bisect import bisect_right

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        i = p.index('*')
        j = p.index('*', i + 1)
        parts = (p[:i], p[i+1:j], p[j+1:])
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))
            m = len(t)
            pi = [0] * m
            k = 0
            for x in range(1, m):
                while k and t[x] != t[k]:
                    k = pi[k-1]
                if t[x] == t[k]:
                    k += 1
                pi[x] = k
            out = []
            k = 0
            for x, ch in enumerate(s):
                while k and ch != t[k]:
                    k = pi[k-1]
                if ch == t[k]:
                    k += 1
                if k == m:
                    out.append(x-m+1)
                    k = pi[k-1]
            return out

        A, B, C = map(occurrences, parts)
        la, lb, lc = map(len, parts)
        ans = n + 1
        for cs in C:
            bi = bisect_right(B, cs - lb) - 1
            if bi < 0:
                continue
            bs = B[bi]
            ai = bisect_right(A, bs - la) - 1
            if ai < 0:
                continue
            ans = min(ans, cs + lc - A[ai])
        return -1 if ans == n + 1 else ans

