    if not data:
        return
    n, m = data[0], data[1]
    adj = [[] for _ in range(n)]
    idx = 2
    max_z = 0
    for _ in range(m):
        x, y, z = data[idx] - 1, data[idx + 1] - 1, data[idx + 2]
        idx += 3
        max_z = max(max_z, z)
        adj[x].append((y, z))
        adj[y].append((x, z))

    p = [None] * n
    ans = [0] * n
    bits = max_z.bit_length()
    for start in range(n):
        if p[start] is not None:
            continue
        p[start] = 0
        stack = [start]
        comp = []
        while stack:
            v = stack.pop()
            comp.append(v)
            for w, z in adj[v]:
                want = p[v] ^ z
                if p[w] is None:
                    p[w] = want
                    stack.append(w)
