import sys

def main():
    data=sys.stdin.buffer.read().split()
    K=int(data[0]); S=data[1]; T=data[2]
    n=len(S); m=len(T)
    if abs(n-m)>K:
        print('No'); return
    # diagonal k = i-j; x=i
    x=0
    while x<n and x<m and S[x]==T[x]: x+=1
    prev={0:x}
    if x==n and x==m:
        print('Yes'); return
    for d in range(1,K+1):
        cur={}
        for k in range(-d,d+1):
            best=-1
            # carry state: at most d-1 edits (no extra edit)
            if k in prev: best=max(best,prev[k])
            # deletion from S: k increases
            if k-1 in prev: best=max(best,prev[k-1]+1)
            # insertion into S: k decreases
            if k+1 in prev: best=max(best,prev[k+1])
            # substitution
            if k in prev: best=max(best,prev[k]+1)
            j=best-k
            if best < 0 or best>n or j<0 or j>m: continue
            while best<n and j<m and S[best]==T[j]:
                best+=1; j+=1
            cur[k]=best
            if best==n and j==m:
                print('Yes'); return
        prev=cur
    print('No')
