class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        order = []
        stack = [(0, False)]
        while stack:
            x, done = stack.pop()
            if done:
                order.append(x)
            else:
                stack.append((x, True))
                for y in reversed(children[x]):
                    stack.append((y, False))

        pos = [0] * n
        text = []
        size = [1] * n
        for i, x in enumerate(order):
            pos[x] = i
            text.append(s[x])
            if x != 0:
                size[parent[x]] += size[x]

        m = n
        d1 = [0] * m
        l = 0
        r = -1
        for i in range(m):
            k = 1 if i > r else min(d1[l + r - i], r - i + 1)
            while i - k >= 0 and i + k < m and text[i-k] == text[i+k]:
                k += 1
            d1[i] = k
            if i + k - 1 > r:
                l, r = i - k + 1, i + k - 1

        d2 = [0] * m
        l = 0
        r = -1
        for i in range(m):
            k = 0 if i > r else min(d2[l + r - i + 1], r - i + 1)
            while i - k - 1 >= 0 and i + k < m and text[i-k-1] == text[i+k]:
                k += 1
            d2[i] = k
            if i + k - 1 > r:
                l, r = i - k, i + k - 1

        ans = [False] * n
        for x in range(n):
            length = size[x]
            left = pos[x] - length + 1
            right = pos[x]
            if length % 2:
                center = (left + right) // 2
                ans[x] = d1[center] >= length // 2 + 1
            else:
                center = (left + right + 1) // 2
                ans[x] = d2[center] >= length // 2
        return ans

