def brute(A,B):
 # choices per hour 0 skip,1A,2B, disallow consecutive differing drinks unless skipped
 best=0
 for xs in product(range(3),repeat=len(A)):
  ok=True; val=0; prev=None
  for i,x in enumerate(xs):
   if x==0: prev=None
   else:
    if prev is not None and prev!=x: ok=False;break
    val+=(A if x==1 else B)[i];prev=x
  # This formulation allows switch after a skipped hour as intended, but skips can be arbitrary
  if ok: best=max(best,val)
 return best
for n in range(3,8):
 for A in product(range(1,4),repeat=n):
  for B in product(range(1,4),repeat=n):
   if alg(A,B)!=brute(A,B): print('bad', A,B,alg(A,B),brute(A,B));raise SystemExit
