class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        mins = [None] * k
        mins[0] = 0
        prefix = 0
        answer = -10**30
        for i, x in enumerate(nums, 1):
            prefix += x
            r = i % k
            if mins[r] is not None:
                answer = max(answer, prefix - mins[r])
            if mins[r] is None or prefix < mins[r]:
                mins[r] = prefix
        return answer

