import random

def fast(a,k):
    mins=[None]*k; mins[0]=0; p=0; ans=-10**30
    for i,x in enumerate(a,1):
        p+=x; r=i%k
        if mins[r] is not None: ans=max(ans,p-mins[r])
        if mins[r] is None or p<mins[r]: mins[r]=p
    return ans

def brute(a,k):
    ans=-10**30
    for i in range(len(a)):
        s=0
        for j in range(i,len(a)):
            s+=a[j]
            if (j-i+1)%k==0: ans=max(ans,s)
    return ans
for n in range(1,15):
    for _ in range(1000):
        a=[random.randint(-10,10) for _ in range(n)]
        k=random.randint(1,n)
        assert fast(a,k)==brute(a,k),(a,k,fast(a,k),brute(a,k))
print('ok')

